-- Add a reusable 150-sentence situational deck with highlighted vocabulary and audio.
insert into public.template_decks (slug, name, description, level)
values (
  'ban-hang-cham-soc-khach-hang-150-cau',
  'Bán hàng và chăm sóc khách hàng - 150 câu',
  '150 câu tiếng Trung thực tế cho bán hàng và chăm sóc khách hàng: tìm hiểu nhu cầu, tư vấn sản phẩm, báo giá, thương lượng, chốt đơn, phản hồi sau bán và xử lý khiếu nại. Mỗi câu có pinyin, nghĩa tiếng Việt, 1-2 từ mới được highlight và audio tạo sẵn.',
  'Luyện câu'
)
on conflict (slug) do update
set name = excluded.name, description = excluded.description, level = excluded.level;

with target_deck as (
  select id from public.template_decks where slug = 'ban-hang-cham-soc-khach-hang-150-cau'
)
insert into public.template_sentence_cards (
  template_deck_id, sentence_cn, sentence_pinyin, sentence_vi,
  vocab_json, sentence_audio_url, position
)
select
  target_deck.id, card.sentence_cn, card.sentence_pinyin,
  card.sentence_vi, card.vocab_json::jsonb,
  card.sentence_audio_url, card.position
from target_deck
cross join (
  values
    ('请问您今天需要什么帮助？', 'Qǐngwèn nín jīntiān xūyào shénme bāngzhù？', 'Xin hỏi hôm nay quý khách cần trợ giúp gì?', '[{"chinese":"帮助","pinyin":"bāngzhù","meaning_vi":"trợ giúp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-ccd765afb710f678a08fcc62.mp3', 1),
    ('您打算将产品用于什么场合？', 'Nín dǎsuàn jiāng chǎnpǐn yòng yú shénme chǎnghé？', 'Quý khách dự định sử dụng sản phẩm trong dịp nào?', '[{"chinese":"场合","pinyin":"chǎnghé","meaning_vi":"dịp, hoàn cảnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-1660505088e0dac6f20b71dc.mp3', 2),
    ('请问您的预算大概是多少？', 'Qǐngwèn nín de yùsuàn dàgài shì duōshǎo？', 'Xin hỏi ngân sách dự kiến của quý khách là bao nhiêu?', '[{"chinese":"预算","pinyin":"yùsuàn","meaning_vi":"ngân sách"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-a80ab3adc7212317895d7e6d.mp3', 3),
    ('这种产品需要多大尺寸？', 'Zhè zhǒng chǎnpǐn xūyào duō dà chǐcùn？', 'Sản phẩm này quý khách cần kích thước bao nhiêu?', '[{"chinese":"尺寸","pinyin":"chǐcùn","meaning_vi":"kích thước"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d3af8f921f320c92de524fee.mp3', 4),
    ('您喜欢哪种颜色和款式？', 'Nín xǐhuan nǎ zhǒng yánsè hé kuǎnshì？', 'Quý khách thích màu sắc và kiểu dáng nào?', '[{"chinese":"颜色","pinyin":"yánsè","meaning_vi":"màu sắc"},{"chinese":"款式","pinyin":"kuǎnshì","meaning_vi":"kiểu dáng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d645cf35b88e47653a933126.mp3', 5),
    ('请问您期望什么时候收到货？', 'Qǐngwèn nín qīwàng shénme shíhòu shōudào huò？', 'Xin hỏi quý khách mong muốn khi nào nhận được hàng?', '[{"chinese":"期望","pinyin":"qīwàng","meaning_vi":"mong muốn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-9d8bf57e02202c2540ccfb5d.mp3', 6),
    ('您以前用过类似产品吗？', 'Nín yǐqián yòng guò lèisì chǎnpǐn ma？', 'Quý khách đã từng sử dụng sản phẩm tương tự chưa?', '[{"chinese":"类似","pinyin":"lèisì","meaning_vi":"tương tự"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-52cd46ed130252dc97eddaa1.mp3', 7),
    ('您最看重产品的哪些方面？', 'Nín zuì kànzhòng chǎnpǐn de nǎxiē fāngmiàn？', 'Quý khách quan trọng nhất những khía cạnh nào của sản phẩm?', '[{"chinese":"看重","pinyin":"kànzhòng","meaning_vi":"đánh giá cao, quan trọng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-b37d12955fcf4a7da9a2dff8.mp3', 8),
    ('请问这是为个人还是企业购买？', 'Qǐngwèn zhè shì wèi gèrén háishì qǐyè gòumǎi？', 'Xin hỏi đây là mua cho cá nhân hay doanh nghiệp?', '[{"chinese":"企业","pinyin":"qǐyè","meaning_vi":"doanh nghiệp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-8233a54749e08857d31ca451.mp3', 9),
    ('麻烦您提供一下联系方式方便跟进。', 'Máfan nín tígōng yīxià liánxì fāngshì fāngbiàn gēnjìn。', 'Xin quý khách vui lòng cung cấp thông tin liên lạc để tiện theo dõi.', '[{"chinese":"联系方式","pinyin":"liánxì fāngshì","meaning_vi":"thông tin liên lạc"},{"chinese":"跟进","pinyin":"gēnjìn","meaning_vi":"theo dõi, tiếp tục xử lý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-fbef1df4966eda25134a73e6.mp3', 10),
    ('让我确认一下您的需求以免疏漏。', 'Ràng wǒ quèrèn yīxià nín de xūqiú yǐmiǎn shūlòu。', 'Để tôi xác nhận lại nhu cầu của quý khách để tránh thiếu sót.', '[{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"},{"chinese":"需求","pinyin":"xūqiú","meaning_vi":"nhu cầu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-c407b6cae43e0582774551ba.mp3', 11),
    ('如果您需要帮助，请随时告诉我们。', 'Rúguǒ nín xūyào bāngzhù，qǐng suíshí gàosù wǒmen。', 'Nếu quý khách cần trợ giúp, xin cứ thông báo cho chúng tôi bất cứ lúc nào.', '[{"chinese":"随时","pinyin":"suíshí","meaning_vi":"bất cứ lúc nào"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-9e96679ee65ab0bf667ac9bf.mp3', 12),
    ('您希望我们根据什么标准推荐？', 'Nín xīwàng wǒmen gēnjù shénme biāozhǔn tuījiàn？', 'Quý khách mong muốn chúng tôi dựa trên tiêu chuẩn nào để tư vấn?', '[{"chinese":"标准","pinyin":"biāozhǔn","meaning_vi":"tiêu chuẩn"},{"chinese":"推荐","pinyin":"tuījiàn","meaning_vi":"gợi ý, đề xuất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-3166ed90befe6057c6f4db2c.mp3', 13),
    ('请您告诉我对颜色和款式的偏好。', 'Qǐng nín gàosù wǒ duì yánsè hé kuǎnshì de piānhào。', 'Xin quý khách cho biết sở thích về màu sắc và kiểu dáng.', '[{"chinese":"偏好","pinyin":"piānhào","meaning_vi":"sở thích cá nhân"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-e745d8be6a2cf59d6d60f63c.mp3', 14),
    ('您是否有特别关注的功能需求？', 'Nín shìfǒu yǒu tèbié guānzhù de gōngnéng xūqiú？', 'Quý khách có nhu cầu đặc biệt về chức năng nào không?', '[{"chinese":"关注","pinyin":"guānzhù","meaning_vi":"quan tâm"},{"chinese":"功能","pinyin":"gōngnéng","meaning_vi":"chức năng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-17235456819dbe354d5a9064.mp3', 15),
    ('请问您需要哪些配件或附加服务？', 'Qǐngwèn nín xūyào nǎxiē pèijiàn huò fùjiā fúwù？', 'Xin hỏi quý khách cần những phụ kiện hoặc dịch vụ thêm nào?', '[{"chinese":"配件","pinyin":"pèijiàn","meaning_vi":"phụ kiện"},{"chinese":"附加服务","pinyin":"fùjiā fúwù","meaning_vi":"dịch vụ bổ sung"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d7c520065d4c56642d7561ea.mp3', 16),
    ('您打算什么时候安排付款？', 'Nín dǎsuàn shénme shíhòu ānpái fùkuǎn？', 'Quý khách dự định khi nào thanh toán?', '[{"chinese":"安排","pinyin":"ānpái","meaning_vi":"sắp xếp"},{"chinese":"付款","pinyin":"fùkuǎn","meaning_vi":"thanh toán"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-58172f774f7b79a1ffffabf1.mp3', 17),
    ('您对我们的产品了解多少？', 'Nín duì wǒmen de chǎnpǐn liǎojiě duōshǎo？', 'Quý khách biết rõ đến mức nào về sản phẩm của chúng tôi?', '[{"chinese":"了解","pinyin":"liǎojiě","meaning_vi":"hiểu biết"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-4a5a46825f66efbd7bd759e6.mp3', 18),
    ('请问您对价格范围有什么要求？', 'Qǐngwèn nín duì jiàgé fànwéi yǒu shénme yāoqiú？', 'Xin hỏi quý khách có yêu cầu nào về khoảng giá không?', '[{"chinese":"价格范围","pinyin":"jiàgé fànwéi","meaning_vi":"khoảng giá"},{"chinese":"要求","pinyin":"yāoqiú","meaning_vi":"yêu cầu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-cb4461327873051add702c8d.mp3', 19),
    ('您需要我们为您做特别备注吗？', 'Nín xūyào wǒmen wèi nín zuò tèbié bèizhu mǎ？', 'Quý khách cần chúng tôi ghi chú đặc biệt không?', '[{"chinese":"备注","pinyin":"bèizhu","meaning_vi":"ghi chú"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-aada4426fe386a399c664647.mp3', 20),
    ('您希望这些产品适合哪些使用环境？', 'Nín xīwàng zhèxiē chǎnpǐn shìhé nǎxiē shǐyòng huánjìng？', 'Quý khách mong muốn sản phẩm phù hợp với môi trường sử dụng nào?', '[{"chinese":"适合","pinyin":"shìhé","meaning_vi":"phù hợp"},{"chinese":"使用环境","pinyin":"shǐyòng huánjìng","meaning_vi":"môi trường sử dụng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-a9e1d96cd41de8d5848b4b6e.mp3', 21),
    ('请问您有其他特别的需求吗？', 'Qǐngwèn nín yǒu qítā tèbié de xūqiú ma？', 'Xin hỏi quý khách có yêu cầu đặc biệt nào khác không?', '[{"chinese":"特别","pinyin":"tèbié","meaning_vi":"đặc biệt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-53d853228c5bed89c8c23287.mp3', 22),
    ('您习惯通过哪种渠道购买？', 'Nín xíguàn tōngguò nǎ zhǒng qúdào gòumǎi？', 'Quý khách thường quen mua hàng qua kênh nào?', '[{"chinese":"渠道","pinyin":"qúdào","meaning_vi":"kênh (bán hàng)"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-ae6e8710a6bc73c946c6dc5b.mp3', 23),
    ('请告诉我您使用产品的频率。', 'Qǐng gàosù wǒ nín shǐyòng chǎnpǐn de pínlǜ。', 'Xin cho biết tần suất quý khách sử dụng sản phẩm như thế nào.', '[{"chinese":"频率","pinyin":"pínlǜ","meaning_vi":"tần suất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-9ac9e4732ee42fa641425897.mp3', 24),
    ('您有意向试用我们的样品吗？', 'Nín yǒu yìxiàng shìyòng wǒmen de yàngpǐn ma？', 'Quý khách có ý định thử dùng mẫu sản phẩm của chúng tôi không?', '[{"chinese":"样品","pinyin":"yàngpǐn","meaning_vi":"mẫu sản phẩm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-c1dbb8788a75932aace1595c.mp3', 25),
    ('这款产品采用高强度合金材质，耐用性能优异。', 'Zhè kuǎn chǎnpǐn cǎiyòng gāo qiángdù héjīn cáizhì, nàiyòng xìngnéng yōuyì.', 'Sản phẩm này sử dụng chất liệu hợp kim độ bền cao, có hiệu suất bền bỉ xuất sắc.', '[{"chinese":"材质","pinyin":"cáizhì","meaning_vi":"chất liệu"},{"chinese":"耐用","pinyin":"nàyòng","meaning_vi":"bền, sử dụng lâu bền"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-15f128ffb429b929be053620.mp3', 26),
    ('产品标签上清楚标明了原产地和生产厂家。', 'Chǎnpǐn biāoqiān shàng qīngchu biāomíng le yuánchǎndì hé shēngchǎn chǎngjiā.', 'Nhãn sản phẩm ghi rõ xuất xứ và nhà sản xuất.', '[{"chinese":"原产地","pinyin":"yuánchǎndì","meaning_vi":"xuất xứ"},{"chinese":"生产厂家","pinyin":"shēngchǎn chǎngjiā","meaning_vi":"nhà sản xuất"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-88c3d874834d05fc6c462234.mp3', 27),
    ('这款手机的主要参数包括处理器和内存容量。', 'Zhè kuǎn shǒujī de zhǔyào cānshù bāokuò chǔlǐqì hé nèicún róngliàng.', 'Thông số chính của điện thoại này bao gồm bộ xử lý và dung lượng bộ nhớ.', '[{"chinese":"参数","pinyin":"cānshù","meaning_vi":"thông số"},{"chinese":"处理器","pinyin":"chǔlǐqì","meaning_vi":"bộ xử lý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-c7cec24003f186002a32fead.mp3', 28),
    ('与上款相比，这个型号电池容量更大，但价格稍高。', 'Yǔ shàng kuǎn xiāngbǐ, zhège xínghào diànchí róngliàng gèng dà, dàn jiàgé shāo gāo.', 'So với mẫu trước, mẫu này dung lượng pin lớn hơn nhưng giá hơi cao hơn.', '[{"chinese":"电池容量","pinyin":"diànchí róngliàng","meaning_vi":"dung lượng pin"},{"chinese":"型号","pinyin":"xínghào","meaning_vi":"mẫu mã, loại máy"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-3f5187958ea5f6f2e531f6a7.mp3', 29),
    ('这款产品的优点是设计简洁且操作方便。', 'Zhè kuǎn chǎnpǐn de yōudiǎn shì shèjì jiǎnjié qiě cāozuò fāngbiàn.', 'Ưu điểm của sản phẩm này là thiết kế đơn giản và thao tác dễ dàng.', '[{"chinese":"优点","pinyin":"yōudiǎn","meaning_vi":"ưu điểm"},{"chinese":"设计","pinyin":"shèjì","meaning_vi":"thiết kế"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-ebfb65235f8c1bfdb9022f3a.mp3', 30),
    ('需要说明的是，这款材质容易刮花，使用时请注意保护。', 'Xūyào shuōmíng de shì, zhè kuǎn cáizhì róngyì guā huā, shǐyòng shí qǐng zhùyì bǎohù.', 'Cần giải thích rằng chất liệu này dễ bị xước, khi sử dụng xin chú ý bảo vệ.', '[{"chinese":"容易","pinyin":"róngyì","meaning_vi":"dễ dàng"},{"chinese":"保护","pinyin":"bǎohù","meaning_vi":"bảo vệ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-aa353a1abfd2a67060c19ef5.mp3', 31),
    ('正确使用方法是在清洁干燥的表面轻轻按压。', 'Zhèngquè shǐyòng fāngfǎ shì zài qīngjié gānzào de biǎomiàn qīngqīng ànyā.', 'Cách sử dụng đúng là nhẹ nhàng nhấn lên bề mặt sạch và khô.', '[{"chinese":"使用方法","pinyin":"shǐyòng fāngfǎ","meaning_vi":"cách sử dụng"},{"chinese":"清洁","pinyin":"qīngjié","meaning_vi":"làm sạch"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d656d175e2661dc54f4d259b.mp3', 32),
    ('此产品享有一年的保修服务，保障您的权益。', 'Cǐ chǎnpǐn xiǎngyǒu yī nián de bǎoxiū fúwù, bǎozhàng nín de quányì.', 'Sản phẩm này được bảo hành một năm để bảo vệ quyền lợi của bạn.', '[{"chinese":"保修","pinyin":"bǎoxiū","meaning_vi":"bảo hành"},{"chinese":"权益","pinyin":"quányì","meaning_vi":"quyền lợi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-b10e3140742969dedc4d8d05.mp3', 33),
    ('目前这款产品在仓库里有现货，可以立即发货。', 'Mùqián zhè kuǎn chǎnpǐn zài cāngkù lǐ yǒu xiànhuò, kěyǐ lìjí fā huò.', 'Hiện sản phẩm này có sẵn trong kho, có thể giao ngay.', '[{"chinese":"现货","pinyin":"xiànhuò","meaning_vi":"hàng có sẵn"},{"chinese":"发货","pinyin":"fā huò","meaning_vi":"giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-81c1c33f22f9517459b6a871.mp3', 34),
    ('如果您需要，我们可以推荐性能相似的替代型号。', 'Rúguǒ nín xūyào, wǒmen kěyǐ tuījiàn xìngnéng xiāngsì de tìdài xínghào.', 'Nếu bạn cần, chúng tôi có thể giới thiệu mẫu thay thế có hiệu năng tương tự.', '[{"chinese":"替代","pinyin":"tìdài","meaning_vi":"thay thế"},{"chinese":"型号","pinyin":"xínghào","meaning_vi":"mẫu mã, loại máy"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-bd4c469fb57ac47116e8df57.mp3', 35),
    ('欢迎您来店里亲自体验样品效果。', 'Huānyíng nín lái diàn lǐ qīnzì tǐyàn yàngpǐn xiàoguǒ.', 'Chào mừng bạn đến cửa hàng trải nghiệm mẫu thử trực tiếp.', '[{"chinese":"体验","pinyin":"tǐyàn","meaning_vi":"trải nghiệm"},{"chinese":"样品","pinyin":"yàngpǐn","meaning_vi":"mẫu thử"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-9b2982c95b4040f2b78ea0d5.mp3', 36),
    ('这款产品特别适合户外运动使用。', 'Zhè kuǎn chǎnpǐn tèbié shìhé hùwài yùndòng shǐyòng.', 'Sản phẩm này đặc biệt phù hợp để sử dụng trong thể thao ngoài trời.', '[{"chinese":"特别","pinyin":"tèbié","meaning_vi":"đặc biệt"},{"chinese":"适合","pinyin":"shìhé","meaning_vi":"phù hợp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-65220c5b8c93cddf68cb8717.mp3', 37),
    ('产品的表面经过特殊处理，防水性能良好。', 'Chǎnpǐn de biǎomiàn jīngguò tèshū chǔlǐ, fángshuǐ xìngnéng liánghǎo.', 'Bề mặt sản phẩm đã trải qua xử lý đặc biệt, khả năng chống nước tốt.', '[{"chinese":"防水","pinyin":"fángshuǐ","meaning_vi":"chống nước"},{"chinese":"处理","pinyin":"chǔlǐ","meaning_vi":"xử lý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-083e64182f697023fcd3937d.mp3', 38),
    ('这款衣服采用纯棉面料，穿着舒适透气。', 'Zhè kuǎn yīfú cǎiyòng chún mián miànliào, chuānzhuó shūshì tòuqì.', 'Chiếc áo này sử dụng chất liệu cotton 100%, mặc thoải mái và thoáng khí.', '[{"chinese":"面料","pinyin":"miànliào","meaning_vi":"chất liệu vải"},{"chinese":"舒适","pinyin":"shūshì","meaning_vi":"thoải mái"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-37b40a1caf09882c16f516f2.mp3', 39),
    ('这款笔记本电脑采用最新的处理器技术。', 'Zhè kuǎn bǐjìběn diànnǎo cǎiyòng zuìxīn de chǔlǐqì jìshù.', 'Chiếc laptop này sử dụng công nghệ bộ xử lý mới nhất.', '[{"chinese":"采用","pinyin":"cǎiyòng","meaning_vi":"sử dụng, áp dụng"},{"chinese":"技术","pinyin":"jìshù","meaning_vi":"kỹ thuật, công nghệ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-28ea705523cb17d8d6afe1d5.mp3', 40),
    ('产品的重量适中，方便携带和搬运。', 'Chǎnpǐn de zhòngliàng shìzhōng, fāngbiàn xiédài hé bānyùn.', 'Trọng lượng sản phẩm vừa phải, thuận tiện mang theo và vận chuyển.', '[{"chinese":"重量","pinyin":"zhòngliàng","meaning_vi":"trọng lượng"},{"chinese":"搬运","pinyin":"bānyùn","meaning_vi":"vận chuyển, khuân vác"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-a1e139f67b47b4c23dc58c81.mp3', 41),
    ('这款产品的尺寸是标准规格，适用于多数场合。', 'Zhè kuǎn chǎnpǐn de chǐcùn shì biāozhǔn guīgé, shìyòng yú duōshù chǎnghé.', 'Kích thước sản phẩm này theo tiêu chuẩn, thích hợp dùng trong nhiều trường hợp.', '[{"chinese":"尺寸","pinyin":"chǐcùn","meaning_vi":"kích thước"},{"chinese":"规格","pinyin":"guīgé","meaning_vi":"quy cách, tiêu chuẩn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-16d5121bb6202b9901924c95.mp3', 42),
    ('材料环保且无异味，更加健康安全。', 'Cáiliào huánbǎo qiě wú yìwèi, gèngjiā jiànkāng ānquán.', 'Chất liệu thân thiện môi trường và không mùi, an toàn và khỏe mạnh hơn.', '[{"chinese":"环保","pinyin":"huánbǎo","meaning_vi":"bảo vệ môi trường"},{"chinese":"安全","pinyin":"ānquán","meaning_vi":"an toàn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-1a3dbcbe5d1a4b18c3a19bd2.mp3', 43),
    ('使用前请仔细阅读产品说明书，确保正确操作。', 'Shǐyòng qián qǐng zǐxì yuèdú chǎnpǐn shuōmíngshū, quèbǎo zhèngquè cāozuò.', 'Trước khi sử dụng xin đọc kỹ hướng dẫn sản phẩm để đảm bảo thao tác đúng.', '[{"chinese":"说明书","pinyin":"shuōmíngshū","meaning_vi":"hướng dẫn sử dụng"},{"chinese":"确保","pinyin":"quèbǎo","meaning_vi":"đảm bảo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-55ac2989aee5aebff972f880.mp3', 44),
    ('产品符合国家标准，质量有保证。', 'Chǎnpǐn fúhé guójiā biāozhǔn, zhìliàng yǒu bǎozhèng.', 'Sản phẩm đáp ứng tiêu chuẩn quốc gia, chất lượng được đảm bảo.', '[{"chinese":"国家标准","pinyin":"guójiā biāozhǔn","meaning_vi":"tiêu chuẩn quốc gia"},{"chinese":"质量","pinyin":"zhìliàng","meaning_vi":"chất lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-e71edd8789cbd77ae654c6f5.mp3', 45),
    ('这款产品支持多种颜色选择，满足不同喜好。', 'Zhè kuǎn chǎnpǐn zhīchí duō zhǒng yánsè xuǎnzé, mǎnzú bùtóng xǐhào.', 'Sản phẩm này hỗ trợ nhiều lựa chọn màu sắc, đáp ứng các sở thích khác nhau.', '[{"chinese":"颜色","pinyin":"yánsè","meaning_vi":"màu sắc"},{"chinese":"选择","pinyin":"xuǎnzé","meaning_vi":"lựa chọn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-00918560c37a64140e6afe4a.mp3', 46),
    ('虽然价格稍高，但性能表现出色，值得投资。', 'Suīrán jiàgé shāo gāo, dàn xìngnéng biǎoxiàn chūsè, zhídé tóuzī.', 'Mặc dù giá hơi cao, nhưng hiệu năng xuất sắc, đáng để đầu tư.', '[{"chinese":"性能","pinyin":"xìngnéng","meaning_vi":"hiệu năng"},{"chinese":"投资","pinyin":"tóuzī","meaning_vi":"đầu tư"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-dce3eea0c01535ca8832244d.mp3', 47),
    ('产品设计符合人体工程学，长时间使用不易疲劳。', 'Chǎnpǐn shèjì fúhé réntǐ gōngchéngxué, cháng shíjiān shǐyòng bù yì píláo.', 'Thiết kế sản phẩm phù hợp với công thái học, sử dụng lâu không dễ mệt mỏi.', '[{"chinese":"人体工程学","pinyin":"réntǐ gōngchéngxué","meaning_vi":"công thái học"},{"chinese":"疲劳","pinyin":"píláo","meaning_vi":"mệt mỏi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d298be256c48bd7b7e2173ba.mp3', 48),
    ('这款产品适合送礼，包装设计高档大方。', 'Zhè kuǎn chǎnpǐn shìhé sòng lǐ, bāozhuāng shèjì gāodàng dàfāng.', 'Sản phẩm này thích hợp làm quà, thiết kế bao bì sang trọng và lịch sự.', '[{"chinese":"包装","pinyin":"bāozhuāng","meaning_vi":"bao bì"},{"chinese":"高档","pinyin":"gāodàng","meaning_vi":"cao cấp, sang trọng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-2816dea1af67f6b655493eaa.mp3', 49),
    ('我们建议在购买前先确认产品的具体参数。', 'Wǒmen jiànyì zài gòumǎi qián xiān quèrèn chǎnpǐn de jùtǐ cānshù.', 'Chúng tôi khuyên bạn nên xác nhận thông số cụ thể của sản phẩm trước khi mua.', '[{"chinese":"建议","pinyin":"jiànyì","meaning_vi":"đề xuất, gợi ý"},{"chinese":"具体","pinyin":"jùtǐ","meaning_vi":"cụ thể"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-1f4e9f31a0c4b51256245dd7.mp3', 50),
    ('这款产品的价格包括增值税，不含运输费用。', 'Zhè kuǎn chǎnpǐn de jiàgé bāokuò zēngzhíshuì, bù hán yùnshū fèiyòng.', 'Giá sản phẩm này đã bao gồm thuế giá trị gia tăng nhưng chưa gồm phí vận chuyển.', '[{"chinese":"增值税","pinyin":"zēngzhíshuì","meaning_vi":"thuế giá trị gia tăng"},{"chinese":"运输费用","pinyin":"yùnshū fèiyòng","meaning_vi":"phí vận chuyển"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-826204f0b483072b1b3e3450.mp3', 51),
    ('批发价格根据购买数量享有不同的折扣优惠。', 'Pīfā jiàgé gēnjù gòumǎi shùliàng xiǎngyǒu bùtóng de zhékòu yōuhuì.', 'Giá bán sỉ được áp dụng chiết khấu khác nhau tùy theo số lượng mua hàng.', '[{"chinese":"批发价格","pinyin":"pīfā jiàgé","meaning_vi":"giá bán sỉ"},{"chinese":"折扣","pinyin":"zhékòu","meaning_vi":"chiết khấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-25d6f7c1b54e8023c0b03e81.mp3', 52),
    ('请问您需要我为您发送正式的报价单吗？', 'Qǐngwèn nín xūyào wǒ wéi nín fāsòng zhèngshì de bàojià dān ma?', 'Xin hỏi quý khách có cần tôi gửi bảng báo giá chính thức không?', '[{"chinese":"报价单","pinyin":"bàojià dān","meaning_vi":"bảng báo giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-b9b19b09ad8aeb5a4da749ee.mp3', 53),
    ('零售价和批发价的差异我可以详细为您说明。', 'Língshòu jià hé pīfā jià de chāyì wǒ kěyǐ xiángxì wèi nín shuōmíng.', 'Tôi có thể giải thích chi tiết cho quý khách sự khác biệt giữa giá lẻ và giá sỉ.', '[{"chinese":"零售价","pinyin":"língshòu jià","meaning_vi":"giá lẻ"},{"chinese":"差异","pinyin":"chāyì","meaning_vi":"sự khác biệt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-5491861709eb579133174032.mp3', 54),
    ('本报价有效期为十五天，逾期需重新确认价格。', 'Běn bàojià yǒuxiàoqī wéi shíwǔ tiān, yúqī xū chóngxīn quèrèn jiàgé.', 'Báo giá này có hiệu lực trong vòng 15 ngày, quá hạn sẽ cần xác nhận lại giá.', '[{"chinese":"有效期","pinyin":"yǒuxiàoqī","meaning_vi":"thời hạn hiệu lực"},{"chinese":"逾期","pinyin":"yúqī","meaning_vi":"quá hạn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-0ffef28095c2718a27950460.mp3', 55),
    ('请您确认使用的货币单位是人民币还是美元。', 'Qǐng nín quèrèn shǐyòng de huòbì dānwèi shì Rénmínbì háishì Měiyuán.', 'Xin quý khách xác nhận đơn vị tiền tệ sử dụng là Nhân dân tệ hay Đô la Mỹ.', '[{"chinese":"货币单位","pinyin":"huòbì dānwèi","meaning_vi":"đơn vị tiền tệ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-1731c7a512b3ef20d089fd4a.mp3', 56),
    ('请问您偏好哪种付款方式，银行转账还是在线支付？', 'Qǐngwèn nín piānhào nǎ zhǒng fùkuǎn fāngshì, yínháng zhuǎnzhàng háishì zàixiàn zhīfù?', 'Xin hỏi quý khách ưu tiên phương thức thanh toán nào, chuyển khoản ngân hàng hay thanh toán trực tuyến?', '[{"chinese":"付款方式","pinyin":"fùkuǎn fāngshì","meaning_vi":"phương thức thanh toán"},{"chinese":"银行转账","pinyin":"yínháng zhuǎnzhàng","meaning_vi":"chuyển khoản ngân hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-dbb53de9fae3b9b6377561ba.mp3', 57),
    ('我们通常需要30%的订金以确认订单。', 'Wǒmen tōngcháng xūyào sānshí bǎi fēnzhī de dìngjīn yǐ quèrèn dìngdān.', 'Chúng tôi thường yêu cầu đặt cọc 30% để xác nhận đơn hàng.', '[{"chinese":"订金","pinyin":"dìngjīn","meaning_vi":"đặt cọc"},{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-c3170e835b739bab79339850.mp3', 58),
    ('发票将在货款全额到账后及时开具。', 'Fāpiào jiāng zài huòkuǎn quán''é dào zhàng hòu jíshí kāijù.', 'Hóa đơn sẽ được xuất ngay khi nhận đủ số tiền thanh toán.', '[{"chinese":"发票","pinyin":"fāpiào","meaning_vi":"hóa đơn"},{"chinese":"及时","pinyin":"jíshí","meaning_vi":"kịp thời"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-9c92af6e9a924bbe466e6771.mp3', 59),
    ('运输费用需根据送货地点单独计算。', 'Yùnshū fèiyòng xū gēnjù sòng huò dìdiǎn dān dú jìsuàn.', 'Phí vận chuyển sẽ được tính riêng dựa trên địa điểm giao hàng.', '[{"chinese":"运输费用","pinyin":"yùnshū fèiyòng","meaning_vi":"phí vận chuyển"},{"chinese":"单独","pinyin":"dān dú","meaning_vi":"riêng biệt, độc lập"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-b176ce1974c7eae2debd0511.mp3', 60),
    ('如果订单量大，我们可以商量更优惠的价格。', 'Rúguǒ dìngdān liàng dà, wǒmen kěyǐ shāngliáng gèng yōuhuì de jiàgé.', 'Nếu đơn hàng số lượng lớn, chúng tôi có thể thương lượng giá ưu đãi hơn.', '[{"chinese":"订单量","pinyin":"dìngdān liàng","meaning_vi":"số lượng đơn hàng"},{"chinese":"优惠","pinyin":"yōuhuì","meaning_vi":"ưu đãi, chiết khấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d18eef44eba94e2616dea87a.mp3', 61),
    ('预付款需在发货前完成，感谢您的配合。', 'Yùfùkuǎn xū zài fāhuò qián wánchéng, gǎnxiè nín de pèihé.', 'Khoản trả trước cần được thanh toán trước khi giao hàng, cảm ơn quý khách hợp tác.', '[{"chinese":"预付款","pinyin":"yùfùkuǎn","meaning_vi":"khoản trả trước"},{"chinese":"配合","pinyin":"pèihé","meaning_vi":"hợp tác"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-7d48dbb52915f955373181a7.mp3', 62),
    ('优惠活动截止日期将在报价单中明确标注。', 'Yōuhuì huódòng jiézhǐ rìqī jiāng zài bàojià dān zhōng míngquè biāozhù.', 'Thời hạn của chương trình ưu đãi sẽ được ghi rõ trong bảng báo giá.', '[{"chinese":"截止日期","pinyin":"jiézhǐ rìqī","meaning_vi":"ngày kết thúc"},{"chinese":"明确","pinyin":"míngquè","meaning_vi":"rõ ràng, minh bạch"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-ee4152785eed9e67e7a45908.mp3', 63),
    ('确认订单后，我们将在三个工作日内发货。', 'Quèrèn dìngdān hòu, wǒmen jiāng zài sān gè gōngzuò rì nèi fāhuò.', 'Sau khi xác nhận đơn hàng, chúng tôi sẽ giao hàng trong 3 ngày làm việc.', '[{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"},{"chinese":"工作日","pinyin":"gōngzuò rì","meaning_vi":"ngày làm việc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-c5454b3cf8094dedf91ddba9.mp3', 64),
    ('我们的报价不含关税，税费由买方负责。', 'Wǒmen de bàojià bù hán guānshuì, shuìfèi yóu mǎifāng fùzé.', 'Báo giá của chúng tôi không bao gồm thuế nhập khẩu, thuế do bên mua chịu trách nhiệm.', '[{"chinese":"关税","pinyin":"guānshuì","meaning_vi":"thuế nhập khẩu"},{"chinese":"负责","pinyin":"fùzé","meaning_vi":"chịu trách nhiệm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-7ffd3731d460dc0fc21b670f.mp3', 65),
    ('请您提供收货地址以便准确计算运费。', 'Qǐng nín tígōng shōuhuò dìzhǐ yǐbiàn zhǔnquè jìsuàn yùnfèi.', 'Xin quý khách cung cấp địa chỉ nhận hàng để tính đúng phí vận chuyển.', '[{"chinese":"收货地址","pinyin":"shōuhuò dìzhǐ","meaning_vi":"địa chỉ nhận hàng"},{"chinese":"运费","pinyin":"yùnfèi","meaning_vi":"phí vận chuyển"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-f84bdab8052d1080ffaa2c57.mp3', 66),
    ('发票类型可以是普通发票或增值税专用发票。', 'Fāpiào lèixíng kěyǐ shì pǔtōng fāpiào huò zēngzhíshuì zhuānyòng fāpiào.', 'Loại hóa đơn có thể là hóa đơn thường hoặc hóa đơn giá trị gia tăng chuyên dùng.', '[{"chinese":"发票类型","pinyin":"fāpiào lèixíng","meaning_vi":"loại hóa đơn"},{"chinese":"专用发票","pinyin":"zhuānyòng fāpiào","meaning_vi":"hóa đơn chuyên dùng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d510a225f361b693264bee3c.mp3', 67),
    ('请注意，所有价格均以人民币计价。', 'Qǐng zhùyì, suǒyǒu jiàgé jūn yǐ Rénmínbì jìjià.', 'Xin lưu ý, tất cả giá đều được tính bằng đồng Nhân dân tệ.', '[{"chinese":"计价","pinyin":"jìjià","meaning_vi":"định giá, tính giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-5ea793db9b2f40f9d2781a9e.mp3', 68),
    ('请问您需要分期付款服务吗？', 'Qǐngwèn nín xūyào fēnqī fùkuǎn fúwù ma?', 'Xin hỏi quý khách có cần dịch vụ thanh toán trả góp không?', '[{"chinese":"分期付款","pinyin":"fēnqī fùkuǎn","meaning_vi":"thanh toán trả góp"},{"chinese":"服务","pinyin":"fúwù","meaning_vi":"dịch vụ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-89dd79c4ae726365d959ba12.mp3', 69),
    ('订单确认后，价格保持不变，感谢您的理解。', 'Dìngdān quèrèn hòu, jiàgé bǎochí bù biàn, gǎnxiè nín de lǐjiě.', 'Sau khi xác nhận đơn hàng, giá sẽ không thay đổi, cảm ơn quý khách thông cảm.', '[{"chinese":"订单确认","pinyin":"dìngdān quèrèn","meaning_vi":"xác nhận đơn hàng"},{"chinese":"保持","pinyin":"bǎochí","meaning_vi":"duy trì, giữ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-c3977fa81f1eb1517ea24f64.mp3', 70),
    ('您可以通过银行转账或支付宝付款。', 'Nín kěyǐ tōngguò yínháng zhuǎnzhàng huò Zhīfùbǎo fùkuǎn.', 'Quý khách có thể thanh toán qua chuyển khoản ngân hàng hoặc Alipay.', '[{"chinese":"支付宝","pinyin":"Zhīfùbǎo","meaning_vi":"Alipay, ví điện tử"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-50e748eebf1c9baee4020041.mp3', 71),
    ('我们建议您在确认订单前仔细核对报价内容。', 'Wǒmen jiànyì nín zài quèrèn dìngdān qián zǐxì héduì bàojià nèiróng.', 'Chúng tôi khuyên quý khách kiểm tra kỹ nội dung báo giá trước khi xác nhận đơn hàng.', '[{"chinese":"核对","pinyin":"héduì","meaning_vi":"đối chiếu, kiểm tra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-e26bc7838ae69da067481be4.mp3', 72),
    ('请问您需要我们出具装箱单和运输单据吗？', 'Qǐngwèn nín xūyào wǒmen chūjù zhuāngxiāng dān hé yùnshū dānjù ma?', 'Xin hỏi quý khách có cần chúng tôi xuất giấy báo đóng gói và vận chuyển không?', '[{"chinese":"装箱单","pinyin":"zhuāngxiāng dān","meaning_vi":"phiếu đóng gói"},{"chinese":"运输单据","pinyin":"yùnshū dānjù","meaning_vi":"giấy tờ vận chuyển"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-88ee6c61770edb74b2aec3fb.mp3', 73),
    ('请您提前告知是否需要增值税发票以便安排。', 'Qǐng nín tíqián gàozhī shìfǒu xūyào zēngzhíshuì fāpiào yǐbiàn ānpái.', 'Xin quý khách thông báo sớm có cần hóa đơn VAT để chúng tôi sắp xếp.', '[{"chinese":"增值税发票","pinyin":"zēngzhíshuì fāpiào","meaning_vi":"hóa đơn VAT"},{"chinese":"安排","pinyin":"ānpái","meaning_vi":"sắp xếp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-3d2bfb9ff736bb5fa555401e.mp3', 74),
    ('所有价格均为含税价，详见报价单说明。', 'Suǒyǒu jiàgé jūn wèi hán shuì jià, xiáng jiàn bàojià dān shuōmíng.', 'Tất cả giá đã bao gồm thuế, chi tiết vui lòng xem phần giải thích trong bảng báo giá.', '[{"chinese":"含税价","pinyin":"hán shuì jià","meaning_vi":"giá đã gồm thuế"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-cb48263dc4efd8079d274e6c.mp3', 75),
    ('请问您对当前报价有何看法，是否考虑调整价格？', 'Qǐngwèn nín duì dāngqián bàojià yǒu hé kànfǎ, shìfǒu kǎolǜ tiáozhěng jiàgé?', 'Xin hỏi quý khách có ý kiến gì về báo giá hiện tại, có cân nhắc điều chỉnh giá không?', '[{"chinese":"报价","pinyin":"bàojià","meaning_vi":"báo giá"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-40f43211f0104a529388bef5.mp3', 76),
    ('若订购数量增加，我们可以提供更优惠的折扣。', 'Ruò dìnggòu shùliàng zēngjiā, wǒmen kěyǐ tígōng gèng yōuhuì de zhékòu.', 'Nếu tăng số lượng đặt hàng, chúng tôi có thể cung cấp chiết khấu ưu đãi hơn.', '[{"chinese":"折扣","pinyin":"zhékòu","meaning_vi":"chiết khấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-0d4e6a3f6e13c4ad4770af05.mp3', 77),
    ('我需要向上级申请审批您的价格要求，请稍等。', 'Wǒ xūyào xiàng shàngjí shēnqǐng shěnpī nín de jiàgé yāoqiú, qǐng shāoděng.', 'Tôi cần xin phê duyệt yêu cầu giá của quý khách từ cấp trên, xin đợi một chút.', '[{"chinese":"审批","pinyin":"shěnpī","meaning_vi":"phê duyệt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-0d461be0693d06fc1db04ce0.mp3', 78),
    ('增加订购量能够为您争取更合理的价格。', 'Zēngjiā dìnggòu liàng nénggòu wèi nín zhēngqǔ gèng hélǐ de jiàgé.', 'Tăng số lượng đặt hàng có thể giúp quý khách đạt được mức giá hợp lý hơn.', '[{"chinese":"增加","pinyin":"zēngjiā","meaning_vi":"tăng thêm"},{"chinese":"订购量","pinyin":"dìnggòu liàng","meaning_vi":"số lượng đặt hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-b33b6a41ffb8e6541c2a6be8.mp3', 79),
    ('运输费用会根据送货地址另行计算，请您确认。', 'Yùnshū fèiyòng huì gēnjù sònghuò dìzhǐ lìngxíng jìsuàn, qǐng nín quèrèn.', 'Phí vận chuyển sẽ được tính riêng theo địa chỉ giao hàng, xin quý khách xác nhận.', '[{"chinese":"运输费用","pinyin":"yùnshū fèiyòng","meaning_vi":"phí vận chuyển"},{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-7b770f29459e41ea28b3ba6b.mp3', 80),
    ('我们预计的交货日期是否符合您的计划？', 'Wǒmen yùjì de jiāohuò rìqī shìfǒu fúhé nín de jìhuà?', 'Ngày giao hàng dự kiến có phù hợp với kế hoạch của quý khách không?', '[{"chinese":"交货日期","pinyin":"jiāohuò rìqī","meaning_vi":"ngày giao hàng"},{"chinese":"预计","pinyin":"yùjì","meaning_vi":"dự kiến"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-0386aa81d7ff53cd5cb50de1.mp3', 81),
    ('如果需要，我们可以推荐性能相似的替代产品。', 'Rúguǒ xūyào, wǒmen kěyǐ tuījiàn xìngnéng xiāngsì de tìdài chǎnpǐn.', 'Nếu cần, chúng tôi có thể đề xuất sản phẩm thay thế có hiệu năng tương tự.', '[{"chinese":"替代","pinyin":"tìdài","meaning_vi":"thay thế"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-06f6194641a51bbf9b9ed3e2.mp3', 82),
    ('请您确认所选产品的样品和数量是否正确。', 'Qǐng nín quèrèn suǒ xuǎn chǎnpǐn de yàngpǐn hé shùliàng shìfǒu zhèngquè.', 'Xin quý khách xác nhận mẫu sản phẩm và số lượng đã chọn có đúng không.', '[{"chinese":"样品","pinyin":"yàngpǐn","meaning_vi":"mẫu sản phẩm"},{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-f71a11cc23967feb1640d219.mp3', 83),
    ('请核实收货地址并提供详细联系人信息。', 'Qǐng héshí shōuhuò dìzhǐ bìng tígōng xiángxì liánxì rén xìnxī.', 'Vui lòng kiểm tra lại địa chỉ nhận hàng và cung cấp thông tin người liên hệ chi tiết.', '[{"chinese":"收货地址","pinyin":"shōuhuò dìzhǐ","meaning_vi":"địa chỉ nhận hàng"},{"chinese":"详细","pinyin":"xiángxì","meaning_vi":"chi tiết"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-36d071ffeea8298b16868a41.mp3', 84),
    ('请确认收货人的姓名和联系方式无误。', 'Qǐng quèrèn shōuhuò rén de xìngmíng hé liánxì fāngshì wúwù.', 'Xin xác nhận tên và cách thức liên hệ của người nhận không sai sót.', '[{"chinese":"收货人","pinyin":"shōuhuò rén","meaning_vi":"người nhận hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-eaef6b7e21981996fb2ce5e2.mp3', 85),
    ('根据双方协商，已确定以下订单条款。', 'Gēnjù shuāngfāng xiéshāng, yǐ quèdìng yǐxià dìngdān tiáokuǎn.', 'Dựa trên thỏa thuận hai bên, các điều khoản đơn hàng sau đây đã được xác nhận.', '[{"chinese":"条款","pinyin":"tiáokuǎn","meaning_vi":"điều khoản"},{"chinese":"协商","pinyin":"xiéshāng","meaning_vi":"thương lượng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-2ed8f90866f8e0678340e54d.mp3', 86),
    ('请问您是否准备好确认订购这批商品？', 'Qǐngwèn nín shìfǒu zhǔnbèi hǎo quèrèn dìnggòu zhè pī shāngpǐn?', 'Xin hỏi quý khách đã sẵn sàng xác nhận đặt mua lô hàng này chưa?', '[{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"},{"chinese":"订购","pinyin":"dìnggòu","meaning_vi":"đặt hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-4aac557f2b7ceafac0f8422e.mp3', 87),
    ('您提出的折扣请求我会向主管反映。', 'Nín tíchū de zhékòu qǐngqiú wǒ huì xiàng zhǔguǎn fǎnyìng.', 'Yêu cầu chiết khấu của quý khách tôi sẽ phản ánh với quản lý.', '[{"chinese":"折扣","pinyin":"zhékòu","meaning_vi":"chiết khấu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-baad1b029bd12aba07e9b72c.mp3', 88),
    ('为确保顺利交货，请提供完整订单信息。', 'Wéi quèbǎo shùnlì jiāohuò, qǐng tígōng wánzhěng dìngdān xìnxī.', 'Để đảm bảo giao hàng thuận lợi, xin vui lòng cung cấp đầy đủ thông tin đơn hàng.', '[{"chinese":"完整","pinyin":"wánzhěng","meaning_vi":"đầy đủ, hoàn chỉnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-65df0071719b9a220cc4d046.mp3', 89),
    ('我们可以适当调整价格，但需在批准后执行。', 'Wǒmen kěyǐ shìdàng tiáozhěng jiàgé, dàn xū zài pīzhǔn hòu zhíxíng.', 'Chúng tôi có thể điều chỉnh giá phù hợp nhưng phải thực hiện sau khi được chấp thuận.', '[{"chinese":"调整","pinyin":"tiáozhěng","meaning_vi":"điều chỉnh"},{"chinese":"批准","pinyin":"pīzhǔn","meaning_vi":"phê duyệt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-7bee208c3ac3be4f85f59121.mp3', 90),
    ('如果您希望修改数量，我们可以重新计算价格。', 'Rúguǒ nín xīwàng xiūgǎi shùliàng, wǒmen kěyǐ chóngxīn jìsuàn jiàgé.', 'Nếu quý khách muốn thay đổi số lượng, chúng tôi có thể tính lại giá.', '[{"chinese":"修改","pinyin":"xiūgǎi","meaning_vi":"sửa đổi"},{"chinese":"重新","pinyin":"chóngxīn","meaning_vi":"lại, làm lại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-3687d81d7ca3c97eaf5602e7.mp3', 91),
    ('我们建议增加订单量以获得更佳的优惠条件。', 'Wǒmen jiànyì zēngjiā dìngdān liàng yǐ huòdé gèng jiā de yōuhuì tiáojiàn.', 'Chúng tôi đề xuất tăng số lượng đơn hàng để nhận được điều kiện ưu đãi tốt hơn.', '[{"chinese":"建议","pinyin":"jiànyì","meaning_vi":"đề xuất"},{"chinese":"优惠条件","pinyin":"yōuhuì tiáojiàn","meaning_vi":"điều kiện ưu đãi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-ebb50bd2198d0233a8da3f18.mp3', 92),
    ('运费可根据批量订单协商，您有什么建议？', 'Yùnfèi kě gēnjù pīliàng dìngdān xiéshāng, nín yǒu shénme jiànyì?', 'Phí vận chuyển có thể thương lượng dựa trên đơn hàng số lượng lớn, anh/chị có đề xuất gì không?', '[{"chinese":"运费","pinyin":"yùnfèi","meaning_vi":"phí vận chuyển"},{"chinese":"批量","pinyin":"pīliàng","meaning_vi":"số lượng lớn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-dbc57c3023d83d570fa2418a.mp3', 93),
    ('本协议中确认的价格和条款为最终定稿。', 'Běn xiéyì zhōng quèrèn de jiàgé hé tiáokuǎn wèi zuìzhōng dìnggǎo.', 'Giá và điều khoản được xác nhận trong thỏa thuận này là phiên bản cuối cùng.', '[{"chinese":"协议","pinyin":"xiéyì","meaning_vi":"thỏa thuận"},{"chinese":"最终","pinyin":"zuìzhōng","meaning_vi":"cuối cùng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-bb6353814cc4456845697f8e.mp3', 94),
    ('请确认订单细节无误后，我会帮您完成下单。', 'Qǐng quèrèn dìngdān xìjié wúwù hòu, wǒ huì bāng nín wánchéng xiàdān.', 'Xin xác nhận chi tiết đơn hàng không sai sót, tôi sẽ hỗ trợ quý khách hoàn tất đặt hàng.', '[{"chinese":"细节","pinyin":"xìjié","meaning_vi":"chi tiết"},{"chinese":"下单","pinyin":"xiàdān","meaning_vi":"đặt hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-530bd4553af0c019a4e37c5c.mp3', 95),
    ('订单确认后，我们将在约定时间内安排发货。', 'Dìngdān quèrèn hòu, wǒmen jiàng zài yuēdìng shíjiān nèi ānpái fāhuò.', 'Sau khi xác nhận đơn hàng, chúng tôi sẽ sắp xếp giao hàng đúng thời gian đã thỏa thuận.', '[{"chinese":"订单确认","pinyin":"dìngdān quèrèn","meaning_vi":"xác nhận đơn hàng"},{"chinese":"安排","pinyin":"ānpái","meaning_vi":"sắp xếp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-73d3fb3dbf3d9506f65b16f7.mp3', 96),
    ('请问您方便提供发票抬头信息吗？', 'Qǐngwèn nín fāngbiàn tígōng fāpiào táitóu xìnxī ma?', 'Xin hỏi quý khách có tiện cung cấp thông tin tên hóa đơn không?', '[{"chinese":"发票抬头","pinyin":"fāpiào táitóu","meaning_vi":"tên hóa đơn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-79b0755fb2082bbb0c69a1d2.mp3', 97),
    ('本价格含税，运输费用另计，敬请理解。', 'Běn jiàgé hán shuì, yùnshū fèiyòng lìng jì, jìng qǐng lǐjiě.', 'Giá này đã bao gồm thuế, phí vận chuyển tính riêng, mong quý khách thông cảm.', '[{"chinese":"含税","pinyin":"hán shuì","meaning_vi":"bao gồm thuế"},{"chinese":"理解","pinyin":"lǐjiě","meaning_vi":"hiểu, thông cảm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-0e9d6aec5a032c651af0ee90.mp3', 98),
    ('请您确认是否接受本次订单的所有条款和价格。', 'Qǐng nín quèrèn shìfǒu jiēshòu běncì dìngdān de suǒyǒu tiáokuǎn hé jiàgé.', 'Xin quý khách xác nhận có chấp nhận tất cả điều khoản và giá của đơn hàng này không.', '[{"chinese":"接受","pinyin":"jiēshòu","meaning_vi":"chấp nhận"},{"chinese":"条款","pinyin":"tiáokuǎn","meaning_vi":"điều khoản"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-22c5c2f5eea0a0ed7bf8e1dd.mp3', 99),
    ('为了方便操作，我会帮您整理最终订单确认单。', 'Wèile fāngbiàn cāozuò, wǒ huì bāng nín zhěnglǐ zuìzhōng dìngdān quèrèn dān.', 'Để thuận tiện xử lý, tôi sẽ hỗ trợ quý khách tổng hợp phiếu xác nhận đơn hàng cuối cùng.', '[{"chinese":"整理","pinyin":"zhěnglǐ","meaning_vi":"sắp xếp, tổng hợp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-164b6491000d66eea34e4d20.mp3', 100),
    ('您的订单已经发出，物流公司会尽快送达。', 'Nín de dìngdān yǐjīng fāchū, wùliú gōngsī huì jǐnkuài sòngdá.', 'Đơn hàng của quý khách đã được gửi đi, công ty vận chuyển sẽ giao hàng sớm nhất có thể.', '[{"chinese":"物流","pinyin":"wùliú","meaning_vi":"vận chuyển"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-7a76133833b568fcee5e6b95.mp3', 101),
    ('请您确认是否已经收到包裹，方便我们跟进。', 'Qǐng nín quèrèn shìfǒu yǐjīng shōudào bāoguǒ, fāngbiàn wǒmen gēnjìn.', 'Xin quý khách xác nhận đã nhận được kiện hàng để chúng tôi tiện theo dõi.', '[{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"},{"chinese":"跟进","pinyin":"gēnjìn","meaning_vi":"theo dõi, tiếp tục xử lý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-1a0907ef025e58c781d89d87.mp3', 102),
    ('目前您的订单正在处理中，请耐心等待发货通知。', 'Mùqián nín de dìngdān zhèngzài chǔlǐ zhōng, qǐng nàixīn děngdài fāhuò tōngzhī.', 'Hiện đơn hàng của quý khách đang được xử lý, xin vui lòng chờ thông báo gửi hàng.', '[{"chinese":"处理","pinyin":"chǔlǐ","meaning_vi":"xử lý"},{"chinese":"等待","pinyin":"děngdài","meaning_vi":"chờ đợi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-0f377123f855799564a52a2a.mp3', 103),
    ('您的包裹运单号码已发送，请查收并跟踪物流信息。', 'Nín de bāoguǒ yùndān hàomǎ yǐ fāsòng, qǐng cháshōu bìng gēnzōng wùliú xìnxī.', 'Mã vận đơn kiện hàng của quý khách đã được gửi, xin kiểm tra và theo dõi thông tin vận chuyển.', '[{"chinese":"运单","pinyin":"yùndān","meaning_vi":"vận đơn"},{"chinese":"跟踪","pinyin":"gēnzōng","meaning_vi":"theo dõi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-3685c175babe88034b11d8ef.mp3', 104),
    ('因运输原因，您的货物预计将会延迟送达，望您谅解。', 'Yīn yùnshū yuányīn, nín de huòwù yùjì jiāng huì yánchí sòngdá, wàng nín liàngjiě.', 'Vì lý do vận chuyển, hàng hóa của quý khách dự kiến sẽ giao trễ, mong quý khách thông cảm.', '[{"chinese":"运输","pinyin":"yùnshū","meaning_vi":"vận chuyển"},{"chinese":"延迟","pinyin":"yánchí","meaning_vi":"trì hoãn, chậm trễ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-c1fbe3c477ead807101f07ec.mp3', 105),
    ('请问您对产品的使用感受如何，有什么建议吗？', 'Qǐngwèn nín duì chǎnpǐn de shǐyòng gǎnshòu rúhé, yǒu shénme jiànyì ma?', 'Xin hỏi quý khách cảm nhận khi sử dụng sản phẩm như thế nào, có góp ý gì không?', '[{"chinese":"感受","pinyin":"gǎnshòu","meaning_vi":"cảm nhận"},{"chinese":"建议","pinyin":"jiànyì","meaning_vi":"góp ý, đề nghị"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-6e05543424bd3a8cd73db11c.mp3', 106),
    ('激活保修服务请登录官网并填写保修信息表。', 'Jīhuó bǎoxiū fúwù qǐng dēnglù guānwǎng bìng tiánxiě bǎoxiū xìnxī biǎo.', 'Để kích hoạt bảo hành, xin đăng nhập trang chính thức và điền biểu mẫu thông tin bảo hành.', '[{"chinese":"激活","pinyin":"jīhuó","meaning_vi":"kích hoạt"},{"chinese":"保修","pinyin":"bǎoxiū","meaning_vi":"bảo hành"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-067c48b14967ad75972ae4df.mp3', 107),
    ('请您按时安排设备保养，保持产品最佳状态。', 'Qǐng nín ànshí ānpái shèbèi bǎoyǎng, bǎochí chǎnpǐn zuìjiā zhuàngtài.', 'Xin quý khách sắp xếp bảo trì thiết bị đúng thời gian để giữ sản phẩm trong trạng thái tốt nhất.', '[{"chinese":"安排","pinyin":"ānpái","meaning_vi":"sắp xếp"},{"chinese":"保养","pinyin":"bǎoyǎng","meaning_vi":"bảo dưỡng, bảo trì"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-9eb7c91d2e7bf6acaa18d271.mp3', 108),
    ('如需退换货，请保持商品完好并附上购买凭证。', 'Rú xū tuì huàn huò, qǐng bǎochí shāngpǐn wánhǎo bìng fù shàng gòumǎi píngzhèng.', 'Nếu cần đổi trả hàng, xin giữ sản phẩm nguyên vẹn và kèm theo chứng từ mua hàng.', '[{"chinese":"退换货","pinyin":"tuì huàn huò","meaning_vi":"đổi trả hàng"},{"chinese":"凭证","pinyin":"píngzhèng","meaning_vi":"chứng từ, giấy tờ chứng minh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-83624677ad9b4238daacc710.mp3', 109),
    ('产品说明书已经通过电子邮件发送给您，请查收。', 'Chǎnpǐn shuōmíngshū yǐjīng tōngguò diànzǐ yóujiàn fāsòng gěi nín, qǐng cháshōu.', 'Sách hướng dẫn sản phẩm đã được gửi qua email cho quý khách, xin kiểm tra hộp thư.', '[{"chinese":"说明书","pinyin":"shuōmíngshū","meaning_vi":"hướng dẫn sử dụng"},{"chinese":"电子邮件","pinyin":"diànzǐ yóujiàn","meaning_vi":"thư điện tử, email"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-629f46020ccb440a9296b017.mp3', 110),
    ('感谢您的宝贵反馈，我们会持续改进服务质量。', 'Gǎnxiè nín de bǎoguì fǎnkuì, wǒmen huì chíxù gǎijìn fúwù zhìliàng.', 'Cảm ơn những phản hồi quý giá của quý khách, chúng tôi sẽ không ngừng cải thiện chất lượng dịch vụ.', '[{"chinese":"反馈","pinyin":"fǎnkuì","meaning_vi":"phản hồi"},{"chinese":"持续","pinyin":"chíxù","meaning_vi":"liên tục, tiếp tục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-b492949be84679ea2bfbf1ba.mp3', 111),
    ('如有任何问题，欢迎随时联系我们的客服团队。', 'Rú yǒu rènhé wèntí, huānyíng suíshí liánxì wǒmen de kèfú tuánduì.', 'Nếu có bất kỳ vấn đề nào, xin vui lòng liên hệ đội ngũ chăm sóc khách hàng của chúng tôi bất cứ lúc nào.', '[{"chinese":"客服","pinyin":"kèfú","meaning_vi":"chăm sóc khách hàng"},{"chinese":"团队","pinyin":"tuánduì","meaning_vi":"đội ngũ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-df77021cbbaa89bea28b58f3.mp3', 112),
    ('您的订单已成功确认，谢谢您的信任与支持。', 'Nín de dìngdān yǐ chénggōng quèrèn, xièxiè nín de xìnrèn yǔ zhīchí.', 'Đơn hàng của quý khách đã được xác nhận thành công, cảm ơn sự tin tưởng và ủng hộ của quý khách.', '[{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"},{"chinese":"信任","pinyin":"xìnrèn","meaning_vi":"tin tưởng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-00cc113ebbd8424683b9ecf5.mp3', 113),
    ('请提供准确的收货地址和联系方式以确保配送顺利。', 'Qǐng tígōng zhǔnquè de shōuhuò dìzhǐ hé liánxì fāngshì yǐ quèbǎo pèisòng shùnlì.', 'Xin cung cấp địa chỉ nhận hàng và cách liên lạc chính xác để đảm bảo giao hàng thuận lợi.', '[{"chinese":"收货","pinyin":"shōuhuò","meaning_vi":"nhận hàng"},{"chinese":"配送","pinyin":"pèisòng","meaning_vi":"phân phối, giao hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-4f286f066025a5323cd48c4f.mp3', 114),
    ('订单发货后，我们会提供快递单号供您查询。', 'Dìngdān fāhuò hòu, wǒmen huì tígōng kuàidì dānhào gōng nín cháxún.', 'Sau khi gửi hàng, chúng tôi sẽ cung cấp mã vận đơn để quý khách tra cứu.', '[{"chinese":"快递","pinyin":"kuàidì","meaning_vi":"chuyển phát nhanh"},{"chinese":"查询","pinyin":"cháxún","meaning_vi":"tra cứu, kiểm tra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-07a65ba971e290b2d7353850.mp3', 115),
    ('请问您是否方便反馈一下使用过程中遇到的问题？', 'Qǐngwèn nín shìfǒu fāngbiàn fǎnkuì yīxià shǐyòng guòchéng zhōng yùdào de wèntí?', 'Xin hỏi quý khách có tiện để phản hồi những vấn đề gặp phải trong quá trình sử dụng không?', '[{"chinese":"方便","pinyin":"fāngbiàn","meaning_vi":"thuận tiện"},{"chinese":"过程","pinyin":"guòchéng","meaning_vi":"quá trình"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-911cd269c789c7829dc69bcc.mp3', 116),
    ('请根据保修卡上的说明完成产品激活。', 'Qǐng gēnjù bǎoxiū kǎ shàng de shuōmíng wánchéng chǎnpǐn jīhuó.', 'Xin hoàn thành việc kích hoạt sản phẩm theo hướng dẫn trên thẻ bảo hành.', '[{"chinese":"保修卡","pinyin":"bǎoxiū kǎ","meaning_vi":"thẻ bảo hành"},{"chinese":"完成","pinyin":"wánchéng","meaning_vi":"hoàn thành"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-bf559969956855e42b677517.mp3', 117),
    ('定期保养能延长设备使用寿命，请合理安排。', 'Dìngqī bǎoyǎng néng yáncháng shèbèi shǐyòng shòumìng, qǐng hélǐ ānpái.', 'Bảo dưỡng định kỳ có thể kéo dài tuổi thọ thiết bị, xin quý khách sắp xếp hợp lý.', '[{"chinese":"定期","pinyin":"dìngqī","meaning_vi":"định kỳ"},{"chinese":"寿命","pinyin":"shòumìng","meaning_vi":"tuổi thọ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-a58bff70a42d3f71ac383a63.mp3', 118),
    ('如需换货，请提前联系我们安排退货事宜。', 'Rú xū huàn huò, qǐng tíqián liánxì wǒmen ānpái tuì huò shìyí.', 'Nếu muốn đổi hàng, xin vui lòng liên hệ trước để chúng tôi sắp xếp thủ tục trả hàng.', '[{"chinese":"换货","pinyin":"huàn huò","meaning_vi":"đổi hàng"},{"chinese":"安排","pinyin":"ānpái","meaning_vi":"sắp xếp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-400e12cc3f5158d93c53f8f0.mp3', 119),
    ('我们已收到您的退货申请，正在安排后续处理。', 'Wǒmen yǐ shōudào nín de tuìhuò shēnqǐng, zhèngzài ānpái hòuxù chǔlǐ.', 'Chúng tôi đã nhận được yêu cầu trả hàng của quý khách, đang tiến hành xử lý tiếp theo.', '[{"chinese":"退货","pinyin":"tuìhuò","meaning_vi":"trả hàng"},{"chinese":"申请","pinyin":"shēnqǐng","meaning_vi":"đơn xin, yêu cầu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-466fdbe69286b4836d552c86.mp3', 120),
    ('请保存好购买凭证以便后续售后服务使用。', 'Qǐng bǎocún hǎo gòumǎi píngzhèng yǐbiàn hòuxù shòuhòu fúwù shǐyòng.', 'Xin giữ gìn chứng từ mua hàng để sử dụng cho các dịch vụ sau bán hàng.', '[{"chinese":"凭证","pinyin":"píngzhèng","meaning_vi":"chứng từ"},{"chinese":"售后服务","pinyin":"shòuhòu fúwù","meaning_vi":"dịch vụ hậu mãi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-4477ad460b41a5c6db91b988.mp3', 121),
    ('感谢您的反馈意见，我们会持续提升客户体验。', 'Gǎnxiè nín de fǎnkuì yìjiàn, wǒmen huì chíxù tíshēng kèhù tǐyàn.', 'Cảm ơn ý kiến phản hồi của quý khách, chúng tôi sẽ tiếp tục nâng cao trải nghiệm khách hàng.', '[{"chinese":"提升","pinyin":"tíshēng","meaning_vi":"nâng cao"},{"chinese":"体验","pinyin":"tǐyàn","meaning_vi":"trải nghiệm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-21070a8977aec480da51ed80.mp3', 122),
    ('如果您有任何疑问，请随时联系我们的客服中心。', 'Rúguǒ nín yǒu rènhé yíwèn, qǐng suíshí liánxì wǒmen de kèfú zhōngxīn.', 'Nếu quý khách có bất kỳ thắc mắc nào, xin liên hệ trung tâm chăm sóc khách hàng của chúng tôi bất cứ lúc nào.', '[{"chinese":"疑问","pinyin":"yíwèn","meaning_vi":"nghi vấn, thắc mắc"},{"chinese":"中心","pinyin":"zhōngxīn","meaning_vi":"trung tâm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-f8f4ce74ef74883216b76d2f.mp3', 123),
    ('您的订单已成功签收，感谢您的支持，祝您使用愉快。', 'Nín de dìngdān yǐ chénggōng qiānshōu, gǎnxiè nín de zhīchí, zhù nín shǐyòng yúkuài.', 'Đơn hàng đã được ký nhận thành công, cảm ơn quý khách ủng hộ và chúc quý khách sử dụng sản phẩm vui vẻ.', '[{"chinese":"签收","pinyin":"qiānshōu","meaning_vi":"ký nhận hàng"},{"chinese":"愉快","pinyin":"yúkuài","meaning_vi":"vui vẻ, thoải mái"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-37c7eeed18c6a937408c8934.mp3', 124),
    ('请确认收货信息无误，以便我们及时完成订单。', 'Qǐng quèrèn shōuhuò xìnxī wúwù, yǐbiàn wǒmen jíshí wánchéng dìngdān.', 'Xin xác nhận thông tin nhận hàng đúng để chúng tôi kịp thời hoàn thành đơn hàng.', '[{"chinese":"信息","pinyin":"xìnxī","meaning_vi":"thông tin"},{"chinese":"及时","pinyin":"jíshí","meaning_vi":"kịp thời"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-a2c8f30eeab53fa2ca8b5bd0.mp3', 125),
    ('非常抱歉给您带来了不便，我们会认真核实您的投诉。', 'Fēicháng bàoqiàn gěi nín dàile bùbiàn, wǒmen huì rènzhēn héshí nín de tóusù.', 'Rất xin lỗi vì đã gây phiền toái cho quý khách, chúng tôi sẽ nghiêm túc xác minh khiếu nại của quý khách.', '[{"chinese":"核实","pinyin":"héshí","meaning_vi":"xác minh, kiểm tra"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-7a73289dfbfda7cfb916cd7c.mp3', 126),
    ('为了核对订单，请您提供订单编号。', 'Wèile héduì dìngdān, qǐng nín tígōng dìngdān biānhào.', 'Để kiểm tra đơn hàng, xin quý khách vui lòng cung cấp mã đơn hàng.', '[{"chinese":"订单","pinyin":"dìngdān","meaning_vi":"đơn hàng"},{"chinese":"编号","pinyin":"biānhào","meaning_vi":"mã số"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-4854aded45e9c27bccf4ef3c.mp3', 127),
    ('请您确认收到的商品与订单内容是否一致。', 'Qǐng nín quèrèn shōudào de shāngpǐn yǔ dìngdān nèiróng shìfǒu yízhì.', 'Xin quý khách xác nhận sản phẩm đã nhận có đúng với nội dung đơn hàng hay không.', '[{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"},{"chinese":"内容","pinyin":"nèiróng","meaning_vi":"nội dung"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d5570852567d9a1a3134e626.mp3', 128),
    ('很抱歉商品数量不足，请问您需要补发缺少的部分吗？', 'Hěn bàoqiàn shāngpǐn shùliàng bùzú, qǐngwèn nín xūyào bǔfā quēshǎo de bùfèn ma?', 'Rất xin lỗi số lượng hàng không đủ, xin hỏi quý khách có cần chúng tôi gửi bổ sung phần thiếu không?', '[{"chinese":"数量","pinyin":"shùliàng","meaning_vi":"số lượng"},{"chinese":"补发","pinyin":"bǔfā","meaning_vi":"gửi bổ sung"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-ab760d8a38070577214e993d.mp3', 129),
    ('对于商品破损问题，我们会尽快为您安排退换货。', 'Duìyú shāngpǐn pòsǔn wèntí, wǒmen huì jǐnkuài wèi nín ānpái tuì huàn huò.', 'Về vấn đề sản phẩm hư hỏng, chúng tôi sẽ sắp xếp đổi trả hàng cho quý khách càng sớm càng tốt.', '[{"chinese":"破损","pinyin":"pòsǔn","meaning_vi":"hư hỏng"},{"chinese":"安排","pinyin":"ānpái","meaning_vi":"sắp xếp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-3076b834fc9971236f231dd8.mp3', 130),
    ('关于额外的费用，我们可以详细为您说明收费标准。', 'Guānyú éwài de fèiyòng, wǒmen kěyǐ xiángxì wèi nín shuōmíng shōufèi biāozhǔn.', 'Về các khoản phí bổ sung, chúng tôi có thể giải thích chi tiết cho quý khách về tiêu chuẩn thu phí.', '[{"chinese":"费用","pinyin":"fèiyòng","meaning_vi":"phí tổn"},{"chinese":"标准","pinyin":"biāozhǔn","meaning_vi":"tiêu chuẩn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-7a0c93ed44b615e1a31a0f97.mp3', 131),
    ('您是否考虑更换商品，我们可以为您提供换货服务。', 'Nín shìfǒu kǎolǜ gēnghuàn shāngpǐn, wǒmen kěyǐ wèi nín tígōng huànhuò fúwù.', 'Quý khách có muốn đổi sản phẩm không, chúng tôi có thể cung cấp dịch vụ đổi hàng cho quý khách.', '[{"chinese":"更换","pinyin":"gēnghuàn","meaning_vi":"thay đổi, đổi mới"},{"chinese":"换货","pinyin":"huànhuò","meaning_vi":"đổi hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-d49ca4390e25b4699305f0a1.mp3', 132),
    ('请确认您是否同意我们提出的解决方案。', 'Qǐng quèrèn nín shìfǒu tóngyì wǒmen tíchū de jiějué fāng''àn.', 'Xin vui lòng xác nhận quý khách có đồng ý với phương án giải quyết chúng tôi đưa ra không.', '[{"chinese":"方案","pinyin":"fāng''àn","meaning_vi":"phương án, kế hoạch"},{"chinese":"同意","pinyin":"tóngyì","meaning_vi":"đồng ý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-c594908981a096b563b90976.mp3', 133),
    ('退款处理通常需要三个工作日，我们会尽快为您办理。', 'Tuìkuǎn chǔlǐ tōngcháng xūyào sān gè gōngzuò rì, wǒmen huì jǐnkuài wèi nín bànlǐ.', 'Quy trình hoàn tiền thường mất ba ngày làm việc, chúng tôi sẽ làm thủ tục cho quý khách càng sớm càng tốt.', '[{"chinese":"退款","pinyin":"tuìkuǎn","meaning_vi":"hoàn tiền"},{"chinese":"办理","pinyin":"bànlǐ","meaning_vi":"xử lý, làm thủ tục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-06f8ae96ff1eb5312b6c88a3.mp3', 134),
    ('请您耐心等待，我们会在规定时间内完成处理。', 'Qǐng nín nàixīn děngdài, wǒmen huì zài guīdìng shíjiān nèi wánchéng chǔlǐ.', 'Xin quý khách vui lòng kiên nhẫn chờ đợi, chúng tôi sẽ hoàn thành xử lý trong thời gian quy định.', '[{"chinese":"耐心","pinyin":"nàixīn","meaning_vi":"kiên nhẫn"},{"chinese":"规定","pinyin":"guīdìng","meaning_vi":"quy định"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-e8fa3f4886c08d05612b8b53.mp3', 135),
    ('您的投诉已转交相关部门处理，请您放心。', 'Nín de tóusù yǐ zhuǎnjiāo xiāngguān bùmén chǔlǐ, qǐng nín fàngxīn.', 'Khiếu nại của quý khách đã được chuyển cho bộ phận liên quan xử lý, xin quý khách yên tâm.', '[{"chinese":"转交","pinyin":"zhuǎnjiāo","meaning_vi":"chuyển giao"},{"chinese":"相关","pinyin":"xiāngguān","meaning_vi":"liên quan"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-18e1e9ef90de8fa79acfc284.mp3', 136),
    ('非常感谢您的理解和支持，我们将持续改进服务质量。', 'Fēicháng gǎnxiè nín de lǐjiě hé zhīchí, wǒmen jiāng chíxù gǎijìn fúwù zhìliàng.', 'Rất cảm ơn sự thông cảm và ủng hộ của quý khách, chúng tôi sẽ tiếp tục cải thiện chất lượng dịch vụ.', '[{"chinese":"理解","pinyin":"lǐjiě","meaning_vi":"hiểu, thông cảm"},{"chinese":"改进","pinyin":"gǎijìn","meaning_vi":"cải tiến, cải thiện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-e8b5099ed9814dfd736c5889.mp3', 137),
    ('为了核实问题，能否请您提供购买凭证？', 'Wèile héshí wèntí, néngfǒu qǐng nín tígōng gòumǎi píngzhèng?', 'Để xác minh vấn đề, xin quý khách cung cấp chứng từ mua hàng được không?', '[{"chinese":"凭证","pinyin":"píngzhèng","meaning_vi":"chứng từ, giấy tờ chứng minh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-68eb1ed5774ef797da74664d.mp3', 138),
    ('对于您反映的服务态度问题，我们深感歉意。', 'Duìyú nín fǎnyìng de fúwù tàidù wèntí, wǒmen shēn gǎn qiànyì.', 'Chúng tôi rất lấy làm tiếc về vấn đề thái độ phục vụ mà quý khách phản ánh.', '[{"chinese":"态度","pinyin":"tàidù","meaning_vi":"thái độ"},{"chinese":"歉意","pinyin":"qiànyì","meaning_vi":"lời xin lỗi, sự tiếc nuối"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-0d09bfda354ba1beba9f6cba.mp3', 139),
    ('请您检查包裹是否完好，并确认收到货物。', 'Qǐng nín jiǎnchá bāoguǒ shìfǒu wánhǎo, bìng quèrèn shōudào huòwù.', 'Xin quý khách kiểm tra kiện hàng có nguyên vẹn không và xác nhận đã nhận được hàng.', '[{"chinese":"包裹","pinyin":"bāoguǒ","meaning_vi":"gói hàng"},{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-52c383cdffce2ffaf5dbc557.mp3', 140),
    ('如需退货，请保持商品完整并附上购买发票。', 'Rú xū tuìhuò, qǐng bǎochí shāngpǐn wánzhěng bìng fù shàng gòumǎi fāpiào.', 'Nếu cần trả hàng, xin giữ sản phẩm nguyên vẹn và đính kèm hóa đơn mua hàng.', '[{"chinese":"退货","pinyin":"tuìhuò","meaning_vi":"trả hàng"},{"chinese":"完整","pinyin":"wánzhěng","meaning_vi":"nguyên vẹn, đầy đủ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-bfd6ad67bde012e06959c619.mp3', 141),
    ('请您提供详细的联系方式以便后续跟进处理。', 'Qǐng nín tígōng xiángxì de liánxì fāngshì yǐbiàn hòuxù gēnjìn chǔlǐ.', 'Xin quý khách cung cấp đầy đủ thông tin liên lạc để tiện theo dõi xử lý sau này.', '[{"chinese":"联系方式","pinyin":"liánxì fāngshì","meaning_vi":"cách thức liên lạc"},{"chinese":"后续","pinyin":"hòuxù","meaning_vi":"tiếp theo, tiếp tục"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-6307464ef243fff091001233.mp3', 142),
    ('您的意见对我们非常重要，感谢您宝贵的反馈。', 'Nín de yìjiàn duì wǒmen fēicháng zhòngyào, gǎnxiè nín bǎoguì de fǎnkuì.', 'Ý kiến của quý khách rất quan trọng đối với chúng tôi, cảm ơn sự phản hồi quý giá của quý khách.', '[{"chinese":"宝贵","pinyin":"bǎoguì","meaning_vi":"quý giá"},{"chinese":"反馈","pinyin":"fǎnkuì","meaning_vi":"phản hồi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/ban-hang-cham-soc-khach-hang-150-cau/sentence-3c15d6488c6ca6fef436b435.mp3', 143),
